create or replace function public.epic_unified_notes_for_reservations(p_confirmations text[]) returns setof public.epic_unified_notes language sql stable security definer set search_path=public as $$ select n.* from public.epic_unified_notes n where exists (select 1 from public.team_profiles where user_id=auth.uid() and active and role <> 'workstation') and n.archived_at is null and n.confirmation_code = any(p_confirmations) order by n.created_at desc limit 250 $$;